[
  {
    "statement": "Several methods show effectiveness for restoring understory plant diversity after logging.",
    "citations": []
  },
  {
    "statement": "Natural regeneration appears to be a cost-effective approach for restoring understory plant diversity.",
    "citations": [
      "3876"
    ]
  },
  {
    "statement": "Encouraging natural regeneration in former logged forests can restore species richness and diversity over time.",
    "citations": [
      "3876"
    ]
  },
  {
    "statement": "Tree thinning shows strong evidence of effectiveness for restoring understory plant diversity.",
    "citations": [
      "1211"
    ]
  },
  {
    "statement": "Thinning trees in forests increased the species richness and diversity of understory plants.",
    "citations": [
      "1211"
    ]
  },
  {
    "statement": "Thinning trees in forests increased the density and cover of understory plants.",
    "citations": [
      "1211"
    ]
  },
  {
    "statement": "Prescribed fire demonstrates effectiveness for restoring understory plant diversity.",
    "citations": [
      "1221"
    ]
  },
  {
    "statement": "Prescribed fire increased the species richness and diversity of understory plants.",
    "citations": [
      "1221"
    ]
  },
  {
    "statement": "Group-selection harvesting showed mixed results for restoring understory plants.",
    "citations": [
      "1224"
    ]
  },
  {
    "statement": "Group-selection harvesting increased the cover and diversity of understory plants.",
    "citations": [
      "1224"
    ]
  },
  {
    "statement": "Removing or disturbing leaf litter increased understory plant species richness.",
    "citations": [
      "1246"
    ]
  },
  {
    "statement": "Removing or disturbing leaf litter decreased understory plant cover.",
    "citations": [
      "1246"
    ]
  },
  {
    "statement": "Both passive approaches like natural regeneration and active management techniques like tree thinning can be effective for understory restoration.",
    "citations": []
  },
  {
    "statement": "The reviewed documents do not provide specific cost comparisons between methods for understory restoration.",
    "citations": []
  }
]

[
  {
    "statement": "There is limited evidence specifically about education programmes and forest conservation in South America.",
    "citations": []
  },
  {
    "statement": "For forest education programmes specifically, no evidence was found for their effect on forests.",
    "citations": [
      "1158"
    ]
  },
  {
    "statement": "There is some relevant evidence from South America regarding education and conservation programmes more broadly.",
    "citations": []
  },
  {
    "statement": "One study from Venezuela found no evidence for decreases in yellow-shouldered parrot poaching following an educational programme in local schools.",
    "citations": [
      "274"
    ]
  },
  {
    "statement": "The authors of a Venezuelan study argued that benefits of an educational programme would likely be seen later in the project.",
    "citations": [
      "274"
    ]
  },
  {
    "statement": "One replicated, site comparison study in Colombia found that deforestation rates in community-managed forests did not differ from deforestation rates in forests that were not managed by local communities, or in uninhabited national parks.",
    "citations": [
      "1152"
    ]
  },
  {
    "statement": "A site comparison study in Brazil found that areas where community-based management of fishing practices was implemented had higher abundance of river turtles than areas with no community-based management.",
    "citations": [
      "3681"
    ]
  }
]
